function active$VoucherFilter$(f) {
	f.add_onResponseComplete(on$Filter$ResponseComplete);
	if (!f.getItemValue('ky_truoc_tu')) setDefaultDate(f.getItem('ky_nay_tu'));
	&ReportSign.Filter.Active;
}
/* <flatten type="Javascript"> */
function close$VoucherFilter$(sender) {try {sender.remove_onResponseComplete(on$Filter$ResponseComplete);} catch (ex) {}}
function on$Filter$ResponseComplete(sender, e) {
	var f = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Checking':
			var g = f.grid;
			var x = f.getItemValue('mau_bc');
			g._ValueFormType = x;
			g._hiddenFields = [
				{Fields: 'lk_kn_nt, lk_kt_nt', Value: (x == '10' || x == '20' || x == '30' || x == '40' || x == '60')},
				{Fields: 'ky_nay_nt, ky_truoc_nt', Value: (x == '10' || x == '20'|| x == '30')},
				{Fields: 'lk_kn, lk_kt', Value: (x == '10' || x == '30' || x == '40' || x == '60')}
			];
			g._hiddenForms = [
				{Form: [1, 2, 4, 5, 7, 8, 10, 11, 14, 15, 17, 18, 20, 21, 23, 24], Value: (x == '10' || x == '40')},
				{Form: [0, 1, 3, 4, 6, 7, 9, 10, 13, 14, 16, 17, 19, 20, 22, 23], Value: (x == '20' || x == '50')},
				{Form: [0, 2, 3, 5, 6, 8, 9, 11, 13, 15, 16, 18, 19, 21, 22, 24], Value: (x == '30' || x == '60')}
			];
			var dFrom = f.getItem('ky_nay_tu').value, dTo = f.getItem('ky_nay_den').value, x = f.getItem('form').selectedIndex, y = f.getItem('form').options;
			var formName = y[x].text;
			g._alterTitle = [null, [['%f1', formName, true], ['%d1', dFrom, true], ['%d2', dTo, true]]];
			g._queryFilterString = getQueryFilterString(f, 'form, mau_bc');
			g._dFrom = f.getItemValue('ky_nay_tu'), g._dTo = f.getItemValue('ky_nay_den'), g._dFrom0 = f.getItemValue('ky_truoc_tu'), g._dTo0 = f.getItemValue('ky_truoc_den');
			g._project = f.getItemValue('nh_vv1');
			remove$GridReport$Filter(g);
			break;
		default:
			break;
	}
}
function setDefaultDate(o) {
	var f = o.parentForm;
	var dateFrom = f.getItemValue('ky_nay_tu', null, null, true), dateTo = f.getItemValue('ky_nay_den', null, null, true);
	var sFrom = new Date(dateFrom.getFullYear() - 1, dateFrom.getMonth(), dateFrom.getDate());
	var sTo = new Date(dateTo.getFullYear() - 1, dateTo.getMonth(), dateTo.getDate());

	f.setItemValue('ky_truoc_tu', sFrom);
	f.setItemValue('ky_truoc_den', sTo);
}
function initForm(f) {
	var o = f.getItem('form'), value = f._itemValue.split(String.fromCharCode(255)), text = f._itemText.split(String.fromCharCode(255)), index;
	for (var i = 0; i < value.length; i++) {
		o.options[i] = new Option(text[i], value[i]);
		if (!index && f._defaultForm == value[i]) index = i;
	}
	if (!index) index = 0;
	o.options[index].selected = true;
}
